"""LH_OFF = build('LH_off', False, -8.0)
LH_LIT = build('LH_lit', True, 8.0)

K_LH = 10.0 / 12.458   # итоговая высота маяка (с флагштоком) = 10 м
for ob in LH_OFF + LH_LIT:
    if ob.type == 'MESH':
        for v in ob.data.vertices:
            v.co *= K_LH
        for m in ob.modifiers:
            if m.type == 'SOLIDIFY':
                m.thickness *= K_LH
    else:
        ob.location.z *= K_LH
        ob.data.energy *= K_LH * K_LH
""")
open('lighthouse.py', 'w', encoding='utf-8').write(s)
EOF

